  if (error) {
    return json({ ok: false, error: error.message }, 500);
  }

  await recordAudit(sb, {
    user_id: user.userId,
    action: 'closing_doc_delivered',
    entity_type: 'closing_document',
    entity_id: docId,
    details: { delivered_to: body.deliver_to },
    severity: 'info',
  });

  return json({ ok: true, document: updated });
}

