  useEffect(() => {
    if (!isLoading) {
      setLoadingTimedOut(false);
      return;
    }
    const timer = setTimeout(() => {
      setLoadingTimedOut(true);
      setAuthInitError('IVX startup took too long. Tap below to open Owner Login.');
    }, TABS_LOADING_TIMEOUT_MS);
