import React, { useState, useCallback, useMemo } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  RefreshControl,
  TextInput,
  useWindowDimensions,
  FlatList,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useRouter } from 'expo-router';
import {
  Search,
  MapPin,
  BedDouble,
  Bath,
  Maximize,
  Filter,
  X,
  TrendingUp,
  Building2,
  Landmark,
  Home as HomeIcon,
  Briefcase,
} from 'lucide-react-native';
import Colors from '@/constants/colors';
import { supabase } from '@/lib/supabase';
import { useQuery } from '@tanstack/react-query';
import { useRealtimeTable } from '@/hooks/useRealtimeChannel';
import { ShimmerIndicator } from '@/components/ShimmerIndicator';
import { EmptyState } from '@/components/ProgressiveStates';
import { IVXImage } from '@/components/ivx';
import { formatCurrencyWithDecimals } from '@/lib/formatters';

type PropertyType = 'all' | 'residential' | 'commercial' | 'land' | 'mixed_use';

interface REListing {
  id: string;
  title: string;
  asking_price: number;
  currency_code: string;
  city: string;
  country_iso: string;
  bedrooms: number | null;
  bathrooms: number | null;
  building_size_sqm: number | null;
  lot_size_sqm: number | null;
  property_type_code: string;
  listing_type: string;
  is_featured: boolean;
  images: string[];
  description: string;
  listing_status: string;
}

const TYPE_FILTERS: { key: PropertyType; label: string; icon: typeof HomeIcon }[] = [
  { key: 'all', label: 'All', icon: Building2 },
  { key: 'residential', label: 'Residential', icon: HomeIcon },
  { key: 'commercial', label: 'Commercial', icon: Briefcase },
  { key: 'land', label: 'Land', icon: Landmark },
];

export default function MarketplaceScreen() {
  useRealtimeTable('notifications', [['notifications']]);
  const router = useRouter();
  const { width } = useWindowDimensions();
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<PropertyType>('all');
  const [refreshing, setRefreshing] = useState(false);

  const cardWidth = useMemo(() => {
    if (width < 480) return width - 32;
    if (width < 768) return (width - 48) / 2;
    return (width - 64) / 3;
  }, [width]);

  const { data: properties, isLoading, refetch } = useQuery<REListing[]>({
    queryKey: ['re-marketplace', typeFilter, searchQuery],
    queryFn: async () => {
      let query = supabase
        .from('ivx_re_property_listings')
        .select('*')
        .in('listing_status', ['active', 'under_contract'])
        .eq('is_verified', true)
        .order('is_featured', { ascending: false })
        .order('created_at', { ascending: false })
        .limit(30);

      if (typeFilter !== 'all') {
        query = query.eq('property_type_code', typeFilter);
      }

      if (searchQuery.trim()) {
        query = query.or(
          `title.ilike.%${searchQuery}%,city.ilike.%${searchQuery}%,country_iso.ilike.%${searchQuery}%`
        );
      }

      const { data, error } = await query;
      if (error) throw error;
      return (data || []) as unknown as REListing[];
    },
    staleTime: 1000 * 60 * 2,
  });

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await refetch();
    setRefreshing(false);
  }, [refetch]);

  const featuredProperties = useMemo(
    () => properties?.filter((p) => p.is_featured) || [],
    [properties]
  );

  const regularProperties = useMemo(
    () => properties?.filter((p) => !p.is_featured) || [],
    [properties]
  );

  const renderPropertyCard = useCallback(
    (item: REListing) => {
      const primaryImage = item.images?.[0] || null;
      return (
        <TouchableOpacity
          key={item.id}
          style={[styles.card, { width: cardWidth }]}
          onPress={() => router.push(`/marketplace/${item.id}`)}
          activeOpacity={0.85}
        >
          <View style={styles.cardImageContainer}>
            {primaryImage ? (
              <IVXImage
                uri={primaryImage}
                width={cardWidth}
                height={cardWidth * 0.6}
                style={styles.cardImage}
              />
            ) : (
              <View style={[styles.cardImagePlaceholder, { width: cardWidth, height: cardWidth * 0.6 }]}>
                <Building2 size={32} color={Colors.inactive} />
              </View>
            )}
            {item.is_featured && (
              <View style={styles.featuredBadge}>
                <TrendingUp size={10} color="#000" />
                <Text style={styles.featuredText}>FEATURED</Text>
              </View>
            )}
            <View style={styles.statusBadge}>
              <Text style={styles.statusText}>
                {item.listing_type === 'sale' ? 'FOR SALE' : 'FOR RENT'}
              </Text>
            </View>
          </View>
          <View style={styles.cardBody}>
            <Text style={styles.cardPrice}>
              {formatCurrencyWithDecimals(item.asking_price, item.currency_code || 'USD')}
            </Text>
            <Text style={styles.cardTitle} numberOfLines={1}>
              {item.title}
            </Text>
            <View style={styles.cardLocation}>
              <MapPin size={11} color={Colors.inactive} />
              <Text style={styles.cardLocationText} numberOfLines={1}>
                {item.city || 'Location TBD'}, {item.country_iso || '—'}
              </Text>
            </View>
            <View style={styles.cardDetails}>
              {item.bedrooms != null && (
                <View style={styles.detailItem}>
                  <BedDouble size={12} color={Colors.inactive} />
                  <Text style={styles.detailText}>{item.bedrooms} Beds</Text>
                </View>
              )}
              {item.bathrooms != null && (
                <View style={styles.detailItem}>
                  <Bath size={12} color={Colors.inactive} />
                  <Text style={styles.detailText}>{item.bathrooms} Baths</Text>
                </View>
              )}
              {item.building_size_sqm != null && (
                <View style={styles.detailItem}>
                  <Maximize size={12} color={Colors.inactive} />
                  <Text style={styles.detailText}>{Math.round(item.building_size_sqm)} m²</Text>
                </View>
              )}
            </View>
          </View>
        </TouchableOpacity>
      );
    },
    [cardWidth, router]
  );

  if (isLoading) {
    return (
      <SafeAreaView style={styles.container} edges={['top']}>
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Marketplace</Text>
        </View>
        <ScrollView contentContainerStyle={styles.scrollContent}>
          <View style={styles.filterRow}>
            {TYPE_FILTERS.map((f) => (
              <View key={f.key} style={styles.filterChip}>
                <ShimmerIndicator width={60} height={28} borderRadius={14} />
              </View>
            ))}
          </View>
          <View style={styles.cardGrid}>
            {Array.from({ length: 6 }).map((_, i) => (
              <View key={i} style={[styles.card, { width: cardWidth }]}>
                <ShimmerIndicator width={cardWidth} height={cardWidth * 0.6} borderRadius={0} />
                <View style={styles.cardBody}>
                  <ShimmerIndicator width={100} height={16} borderRadius={4} />
                  <View style={{ height: 6 }} />
                  <ShimmerIndicator width={120} height={12} borderRadius={4} />
                  <View style={{ height: 6 }} />
                  <ShimmerIndicator width={80} height={10} borderRadius={4} />
                </View>
              </View>
            ))}
          </View>
        </ScrollView>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container} edges={['top']}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Marketplace</Text>
        <Text style={styles.headerSubtitle}>
          {properties?.length || 0} verified {properties?.length === 1 ? 'property' : 'properties'}
        </Text>
      </View>

      <View style={styles.searchContainer}>
        <Search size={18} color={Colors.inactive} />
        <TextInput
          style={styles.searchInput}
          placeholder="Search by city, country, or title..."
          placeholderTextColor={Colors.inactive}
          value={searchQuery}
          onChangeText={setSearchQuery}
          autoCapitalize="none"
          autoCorrect={false}
        />
        {searchQuery.length > 0 && (
          <TouchableOpacity onPress={() => setSearchQuery('')}>
            <X size={18} color={Colors.inactive} />
          </TouchableOpacity>
        )}
      </View>

      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.filterRow}
      >
        {TYPE_FILTERS.map((filter) => {
          const Icon = filter.icon;
          const isActive = typeFilter === filter.key;
          return (
            <TouchableOpacity
              key={filter.key}
              style={[styles.filterChip, isActive && styles.filterChipActive]}
              onPress={() => setTypeFilter(filter.key)}
            >
              <Icon size={13} color={isActive ? '#000' : Colors.inactive} />
              <Text style={[styles.filterText, isActive && styles.filterTextActive]}>
                {filter.label}
              </Text>
            </TouchableOpacity>
          );
        })}
      </ScrollView>

      <FlatList
        data={regularProperties}
        keyExtractor={(item) => item.id}
        numColumns={width >= 768 ? 2 : 1}
        contentContainerStyle={styles.listContent}
        columnWrapperStyle={width >= 768 ? styles.row : undefined}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={Colors.active} />
        }
        ListHeaderComponent={
          featuredProperties.length > 0 ? (
            <View style={styles.featuredSection}>
              <Text style={styles.sectionTitle}>Featured</Text>
              <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                contentContainerStyle={styles.featuredScroll}
              >
                {featuredProperties.map(renderPropertyCard)}
              </ScrollView>
            </View>
          ) : null
        }
        ListEmptyComponent={
          <EmptyState
            icon={<Building2 size={48} color={Colors.inactive} />}
            title="No properties found"
            message="Try adjusting your filters or check back soon for new listings."
          />
        }
        renderItem={({ item }) => renderPropertyCard(item)}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.background,
  },
  header: {
    paddingHorizontal: 16,
    paddingTop: 12,
    paddingBottom: 8,
  },
  headerTitle: {
    fontSize: 28,
    fontWeight: '700',
    color: Colors.text,
  },
  headerSubtitle: {
    fontSize: 13,
    color: Colors.inactive,
    marginTop: 2,
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: Colors.surface,
    borderRadius: 12,
    paddingHorizontal: 12,
    marginHorizontal: 16,
    marginBottom: 8,
    height: 44,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  searchInput: {
    flex: 1,
    color: Colors.text,
    fontSize: 14,
    marginLeft: 8,
  },
  filterRow: {
    paddingHorizontal: 16,
    paddingBottom: 8,
    gap: 8,
  },
  filterChip: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 16,
    backgroundColor: Colors.surface,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  filterChipActive: {
    backgroundColor: Colors.active,
    borderColor: Colors.active,
  },
  filterText: {
    fontSize: 12,
    color: Colors.inactive,
    fontWeight: '500',
  },
  filterTextActive: {
    color: '#000',
    fontWeight: '600',
  },
  listContent: {
    padding: 16,
  },
  row: {
    gap: 12,
  },
  featuredSection: {
    marginBottom: 16,
  },
  sectionTitle: {
    fontSize: 18,
    fontWeight: '700',
    color: Colors.text,
    marginBottom: 12,
  },
  featuredScroll: {
    gap: 12,
    paddingRight: 16,
